def analyze(datasets):
    # 明确指定使用包含库存和产品信息的 dataset (index 5)
    stock_data = None
    for d in datasets:
        if 'ending_stock' in d.get('columns', []) and 'product_name_en' in d.get('columns', []):
            stock_data = d
            break

    out = []
    if stock_data:
        rows = stock_data['rows']
        # 构建 DataFrame，使用正确的列名映射
        df = pd.DataFrame({
            'name': [r.get('product_name_en') or r.get('product_name_native') for r in rows], 
            'sku': [r['sku'] for r in rows], 
            'stock': [r['ending_stock'] for r in rows], 
            'sold': [r['units_sold'] for r in rows]
        })

        # 转换数值列
        for c in ['stock', 'sold']:
            df[c] = pd.to_numeric(df[c], errors='coerce')

        # 删除 NaN
        df = df.dropna()

        # 计算可售天数
        df['days'] = df['stock'] / df['sold'] * 30
        df = df.sort_values('days')

        # 生成每个产品的详情
        for _, r in df.iterrows():
            out.append({
                'title': '2026年9月库存与可售天数：' + str(r['name']) + '（' + str(r['sku']) + '）', 
                'detail': '期末库存 ' + str(round(r['stock'], 1)) + '，当期销量 ' + str(round(r['sold'], 1)) + '，预计可售 ' + str(round(r['days'], 1)) + ' 天', 
                'evidence': {'ending_stock': round(r['stock'], 1), 'units_sold': round(r['sold'], 1), 'days_of_supply': round(r['days'], 1)}
            })

        # 生成汇总概览
        out.append({
            'title': '库存周转概览', 
            'detail': '共 ' + str(int(len(df))) + ' 个 SKU 平均可售 ' + str(round(df['days'].mean(), 1)) + ' 天，最短 ' + str(round(df['days'].min(), 1)) + ' 天，最长 ' + str(round(df['days'].max(), 1)) + ' 天', 
            'evidence': {'sku_count': int(len(df)), 'avg_days': round(df['days'].mean(), 1), 'min_days': round(df['days'].min(), 1), 'max_days': round(df['days'].max(), 1)}
        })

    # 处理采购单部分 (datasets[6])
    po = next((d for d in datasets if 'po_number' in d.get('columns', [])), None)
    if po:
        rows = po['rows']
        amt = pd.to_numeric(pd.Series([r['total_amount'] for r in rows]), errors='coerce').dropna()
        eta_dates = [r['eta_date'] for r in rows if r.get('eta_date')] # 过滤可能的空值
        if eta_dates:
            earliest_eta = min(eta_dates)
            latest_eta = max(eta_dates)
        else:
            earliest_eta = 'N/A'
            latest_eta = 'N/A'

        out.append({
            'title': '未完成采购单', 
            'detail': '共 ' + str(len(rows)) + ' 张未完成采购单，全部为 awaiting_payment，合计金额 ' + str(round(amt.sum(), 2)) + '，最早预计到达 ' + str(earliest_eta) + '，最晚 ' + str(latest_eta), 
            'evidence': {'po_count': len(rows), 'total_amount': round(amt.sum(), 2), 'earliest_eta': earliest_eta, 'latest_eta': latest_eta}
        })

    return out
